import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    st = []
    for k in range(n):
        x = int(data[1 + k])
        while x < 0 and st and st[-1] > 0:
            top = st[-1]
            if top > -x:
                st[-1] = top + x
                x = 0
            elif top == -x:
                st.pop()
                x = 0
            else:
                st.pop()
                x = x + top
        if x != 0:
            st.append(x)
    print(' '.join(map(str, st)) if st else 'EMPTY')

